def nth_smallest_good_integer(N):
    def is_good_integer(x):
        while x > 0:
            if (x % 10) % 2 != 0:
                return False
            x //= 10
        return True

    count = 0
    current = 0
    while count < N:
        if is_good_integer(current):
            count += 1
        if count < N:
            current += 1
    return current
